import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = []
EVIDENCE = {}


def add(cat, slug, level, ru, en, options, fr, fe, url, location):
    pairs = [s.split('|') for s in options.split(';')]
    assert len(pairs) == 4 and all(len(pair) == 2 for pair in pairs)
    q = dict(id=f'{cat}_{slug}_0001', categoryId=cat, difficulty=level, type='single_choice', revision=1,
             localizations={'ru': dict(question=ru, explanation=fr), 'en': dict(question=en, explanation=fe)},
             options=[dict(id=f'o{i}', ru=p[0], en=p[1]) for i, p in enumerate(pairs)],
             correctOptionId='o0', sources=[url], image=None)
    OUT.append(q)
    EVIDENCE[q['id']] = dict(url=url, location=location, claim=f'{en} Answer: {pairs[0][1]}. {fe}')


